import os
import json
import csv


def validate_file(filepath):
    """Validate a single CSV file and return a list of check results."""
    results = []
    name = os.path.basename(filepath).replace('.csv', '')

    # Check 1: File exists
    if os.path.exists(filepath):
        results.append({
            "check_name": f"exists_{name}",
            "passed": True,
            "message": f"File {filepath} exists."
        })
    else:
        results.append({
            "check_name": f"exists_{name}",
            "passed": False,
            "message": f"File {filepath} does not exist."
        })
        return results

    # Check 2: File is not empty (non-zero size)
    if os.path.getsize(filepath) > 0:
        results.append({
            "check_name": f"not_empty_{name}",
            "passed": True,
            "message": f"File {filepath} is not empty."
        })
    else:
        results.append({
            "check_name": f"not_empty_{name}",
            "passed": False,
            "message": f"File {filepath} is empty (zero bytes)."
        })
        return results

    # Check 3: File can be read as valid CSV with data rows
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": f"has_data_{name}",
                    "passed": False,
                    "message": f"File {filepath} has no rows."
                })
            elif len(rows) == 1 and all(cell.strip() == '' for cell in rows[0]):
                results.append({
                    "check_name": f"has_data_{name}",
                    "passed": False,
                    "message": f"File {filepath} has only an empty header row."
                })
            else:
                num_rows = len(rows) - 1  # subtract header
                num_cols = len(rows[0])
                results.append({
                    "check_name": f"has_data_{name}",
                    "passed": True,
                    "message": f"File {filepath} is a valid CSV with {num_rows} data rows and {num_cols} columns."
                })
    except Exception as e:
        results.append({
            "check_name": f"has_data_{name}",
            "passed": False,
            "message": f"Error reading {filepath} as CSV: {str(e)}"
        })

    return results


def main():
    files_to_validate = [
        "outputs/t01_selected_indicators.csv",
        "outputs/t05_clean_stops.csv",
        "outputs/t08_pois_clean.csv",
        "outputs/t10_accessibility_scores.csv",
        "outputs/t13_city_clusters.csv",
    ]

    all_results = []
    for filepath in files_to_validate:
        all_results.extend(validate_file(filepath))

    # Ensure output directory exists
    os.makedirs("outputs", exist_ok=True)

    # Write validation summary
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_results, f, indent=2)

    passed = sum(1 for r in all_results if r["passed"])
    failed = sum(1 for r in all_results if not r["passed"])
    print(f"Validation complete: {len(all_results)} checks, {passed} passed, {failed} failed.")
    print(f"Summary written to {output_path}")


if __name__ == "__main__":
    main()
